impl PostfixOperator {
    // The operator precedence.
    fn precedence(&self) -> Precedence {
        7
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, lhs: ast::Expression) -> ast::Expression {
        match self {
            PostfixOperator::Factorial => ast::Expression::Factorial(Box::new(lhs)),
            PostfixOperator::Is(lit) => ast::Expression::Is(Box::new(lhs), lit),
            PostfixOperator::IsNot(lit) => ast::Expression::IsNot(Box::new(lhs), lit),
        }
    }
}
